/ これは単純な TEE を記述する EAT ペイロードです。 /
{ / eat_nonce / 10: h'48df7b172d70b5a18935d0460a73dd71', / oemboot / 262: true, / dbgstat / 263: 2, / disabled-since-boot / / manifests / 272: [ [ 258, / CoAP Content ID for CoSWID /
/ This is a byte-string-wrapped / / payload CoSWID. It gives the TEE / / software name, the version, and / / the name of the file it is in. / / {0: "3a24", / / 12: 1, / / 1: "Acme TEE OS", / / 13: "3.1.4", / / 2: [{31: "Acme TEE OS", 33: 1}, / / {31: "Acme TEE OS", 33: 2}], / / 6: { / / 17: { / / 24: "acme_tee_3.exe" / / } / / } / / } / h' a60064336132340c01016b 41636d6520544545204f530d65332e31 2e340282a2181f6b41636d6520544545 204f53182101a2181f6b41636d652054 4545204f5318210206a111a118186e61 636d655f7465655f332e657865' ] ] }

/ これはソフトウェア（SW）ベンダーが作成したペイロード CoSWID です。 /
/ TEE の SW の名前とバージョンを示し、TEE を構成する 1 つの          /
/ ファイルを列挙しているだけです。                                   /

1398229316({
    / Unique CoSWID ID /    0: "3a24",
    / tag-version /        12: 1,
    / software-name /       1: "Acme TEE OS",
    / software-version /   13: "3.1.4",
    / entity /              2: [
                                   {
        / entity-name /                31: "Acme TEE OS",
        / role        /                33: 1 / tag-creator /
                                   },
                                   {
        / entity-name /                31: "Acme TEE OS",
        / role        /                33: 2 / software-creator /
                                   }
                               ],
    / payload /                6: {
        / ...file /                17: {
            / ...fs-name /             24: "acme_tee_3.exe"
                                   }
                               }
})

/ この例は、サブモジュールを使用して、チップ、ボード、 / / およびデバイス全体についての情報を示すものです。 / / / / メインのアテステーションは、CPU を含み、メインの OS を / / 実行するチップに関連付けられています。鍵を持ち、 / / トークンを生成するのはこのチップです。 / / / / ボードはチップとは異なるベンダーが製造しています。 / / おそらく何らかの汎用の IoT ボードです。 / / / / デバイスは、チップともボードとも異なるベンダーが製造した / / 特定の機器です。 / / / / ここでのボードとデバイスのサブモジュールは、RATS / / アーキテクチャー（RFC 9334）で説明されている典型的な / / ターゲット環境ではありませんが、サブモジュールの有効な / / 使い方です。 /
{ / eat_nonce / 10: h'e253cabedc9eec24ac4e25bcbeaf7765', / ueid / 256: h'0198f50a4ff6c05861c8860d13a638ea', / oemid / 258: h'894823', / IEEE OUI format OEM ID / / hwmodel / 259: h'549dcecc8b987c737b44e40f7c635ce8' / Hash of chip model name /, / hwversion / 260: ["1.3.4", 1], / Multipartnumeric / / swname / 270: "Acme OS", / swversion / 271: ["3.5.5", 1], / oemboot / 262: true, / dbgstat / 263: 3, / permanent-disable / / timestamp (iat) / 6: 1526542894, / submods / 266: { / A submodule to hold some claims about the circuit board / "board" : { / oemid / 258: h'9bef8787eba13e2c8f6e7cb4b1f4619a', / hwmodel / 259: h'ee80f5a66c1fb9742999a8fdab930893' / Hash of board module name /, / hwversion / 260: ["2.0a", 2] / multipartnumeric+sfx / },
/ A submodule to hold claims about the overall device / "device" : { / oemid / 258: 61234, / PEN Format OEM ID / / hwversion / 260: ["4.0", 1] / Multipartnumeric / } } }

/ これは、公開鍵と、それを保護および管理する鍵ストアの実装の / / アテステーションです。鍵ストアの実装は、高レベル OS（HLOS） / / とは別の、セキュリティー指向の実行環境（たとえば信頼できる / / 実行環境（TEE））にあります。鍵ストアがアテスターです。 / / / / HLOS についても、バージョンとブートおよびデバッグの状態だけ / / ですが、いくらかのアテステーションがあります。HLOS は鍵ストア / / よりセキュリティーレベルが低いため、Claims-Set の / / サブモジュールになっています。鍵ストアの実装は HLOS に関する / / 情報にアクセスできるため、それを含めることができます。 / / / / 鍵と、その鍵へのアクセスを許可するために行われたユーザー認証の / / 表示が示されています。これは標準プロトコルの一部ではなく / / 架空の例であるため、これらのラベルはプライベートな空間に / / あります。 /
{ / eat_nonce / 10: h'99b67438dba40743266f70bf75feb1026d5134 97a229bfe8', / oemboot / 262: true, / dbgstat / 263: 2, / disabled-since-boot / / manifests / 272: [ [ 258, / CoAP Content ID. / h'a600683762623334383766 0c000169436172626f6e6974650d6331 2e320e0102a2181f75496e6475737472 69616c204175746f6d6174696f6e1821 02' ] / Above is an encoded CoSWID / / with the following data / / SW Name: "Carbonite" / / SW Vers: "1.2" / / SW Creator: / / "Industrial Automation" / ], / exp / 4: 1634324274, / 2021-10-15T18:57:54Z / / iat / 6: 1634317080, / 2021-10-15T16:58:00Z / -80000 : "fingerprint", -80001 : { / The key -- A COSE_Key / / kty / 1: 2, / EC2, elliptic curve with x & y/ / kid / 2: h'36675c206f96236c3f51f54637b94ced', / curve / -1: 2, / curve is P-256 / / x-coord / -2: h'65eda5a12577c2bae829437fe338701a 10aaa375e1bb5b5de108de439c08551d', / y-coord / -3: h'1e52ed75701163f7f9e40ddf9f341b3d c9ba860af7e0ca7ca7e9eecd0084d19c' },
/ submods / 266 : { "HLOS" : { / submod for high-level OS / / eat_nonce / 10: h'8b0b28782a23d3f6', / oemboot / 262: true, / manifests / 272: [ [ 258, / CoAP Content ID. / h'a600687337 6537346b78380c000168 44726f6964204f530d65 52322e44320e0302a218 1F75496E647573747269 616c204175746f6d6174 696f6e182102' ] / Above is an encoded CoSWID / / with the following data: / / SW Name: "Droid OS" / / SW Vers: "R2.D2" / / SW Creator: / / "Industrial Automation"/ ] } } }

/ この EAT ペイロードは、TEE を持つ IoT デバイス向けのものです。 / / アテステーションは TEE が生成します。IoT OS（TEE ほど安全では / / ない、IoT デバイスのメインの OS）のためのサブモジュールが / / あります。サブモジュールには IoT OS のクレームが含まれます。 / / TEE は IoT OS の測定も行い、その測定値をサブモジュールに / / 入れます。 /
{ / eat_nonce / 10: h'5e19fba4483c7896', / oemboot / 262: true, / dbgstat / 263: 2, / disabled-since-boot / / oemid / 258: h'8945ad', / IEEE CID based / / ueid / 256: h'0198f50a4ff6c05861c8860d13a638ea', / submods / 266: { "OS" : { / oemboot / 262: true, / dbgstat / 263: 2, / disabled-since-boot / / measurements / 273: [ [ 258, / CoAP Content ID /
/ This is a byte-string-wrapped / / evidence CoSWID. It has / / hashes of the main files of / / the IoT OS. / h'a600663463613234350c 17016d41636d6520522d496f542d4f 530d65332e312e3402a2181f724163 6d6520426173652041747465737465 7218210103a11183a318187161636d 655f725f696f745f6f732e65786514 1a0044b349078201582005f6b327c1 73b4192bd2c3ec248a292215eab456 611bf7a783e25c1782479905a31818 6d7265736f75726365732e72736314 1a000c38b10782015820c142b9aba4 280c4bb8c75f716a43c99526694caa be529571f5569bb7dc542f98a31818 6a636f6d6d6f6e2e6c6962141a0023 3d3b0782015820a6a9dcdfb3884da5 f884e4e1e8e8629958c2dbc7027414 43a913e34de9333be6' ] ] } } }

